import{_ as t,o as r,c as e,ag as o}from"./chunks/framework.DXGyWiRo.js";const c=JSON.parse('{"title":"Соглашение о поручении обработки персональных данных","description":"","frontmatter":{},"headers":[],"relativePath":"data-processing-agreement.md","filePath":"data-processing-agreement.md","lastUpdated":null}'),s={name:"data-processing-agreement.md"};function l(n,a,p,i,h,d){return r(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="соглашение-о-поручении-обработки-персональных-данных" tabindex="-1">Соглашение о поручении обработки персональных данных <a class="header-anchor" href="#соглашение-о-поручении-обработки-персональных-данных" aria-label="Permalink to &quot;Соглашение о поручении обработки персональных данных&quot;">​</a></h1><p><strong>ИП Ульянов Алексей Владимирович</strong><br> ОГРНИП 321132600016985<br> Email: <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a></p><p><em>Редакция от 21 апреля 2026 г.</em></p><hr><div class="info custom-block"><p class="custom-block-title">Кому адресован документ</p><p>Настоящее Соглашение адресовано юридическим лицам и индивидуальным предпринимателям — партнёрам GoSMS, которым в процессе использования Сервиса может поручаться обработка персональных данных пользователей в соответствии с ч. 3 ст. 6 Федерального закона от 27.07.2006 № 152-ФЗ «О персональных данных».</p><p>Для физических лиц — пользователей Сервиса порядок обработки данных описан в <a href="/privacy-policy">Политике конфиденциальности</a>.</p></div><p>Настоящее Соглашение о поручении обработки персональных данных (далее — <strong>Соглашение</strong>) заключается между <strong>ИП Ульяновым Алексеем Владимировичем</strong> (ОГРНИП 321132600016985, далее — <strong>Оператор</strong>) и организацией или лицом, действующим в качестве <strong>оператора по поручению</strong> (далее — <strong>Поверенный</strong>) при использовании Сервиса GoSMS.</p><p>Соглашение вступает в силу в момент акцепта условий оферты при регистрации в сервисе GoSMS, если Поверенный действует в качестве организации (юридического лица или ИП), обрабатывающей данные пользователей GoSMS.</p><h2 id="_1-предмет-соглашения" tabindex="-1">1. Предмет соглашения <a class="header-anchor" href="#_1-предмет-соглашения" aria-label="Permalink to &quot;1. Предмет соглашения&quot;">​</a></h2><p>1.1. Оператор поручает Поверенному обработку персональных данных субъектов, пользующихся Сервисом GoSMS (пользователи, абоненты, клиенты Поверенного), исключительно в целях и объёме, необходимых для предоставления услуг через Сервис.</p><p>1.2. Поверенный осуществляет обработку персональных данных только в соответствии с инструкциями Оператора и условиями настоящего Соглашения.</p><h2 id="_2-перечень-обрабатываемых-данных" tabindex="-1">2. Перечень обрабатываемых данных <a class="header-anchor" href="#_2-перечень-обрабатываемых-данных" aria-label="Permalink to &quot;2. Перечень обрабатываемых данных&quot;">​</a></h2><p>2.1. В рамках поручения Поверенный обрабатывает следующие категории персональных данных:</p><table tabindex="0"><thead><tr><th>Категория данных</th><th>Состав</th></tr></thead><tbody><tr><td>Идентификационные</td><td>Имя получателя (при наличии)</td></tr><tr><td>Контактные</td><td>Номер телефона получателя SMS</td></tr><tr><td>Данные сообщений</td><td>Содержание SMS-сообщений, дата и время отправки</td></tr></tbody></table><p>2.2. Поверенный <strong>не вправе</strong> обрабатывать специальные категории персональных данных (ст. 10 ФЗ-152) без получения явного согласия и уведомления Оператора.</p><h2 id="_3-цели-обработки" tabindex="-1">3. Цели обработки <a class="header-anchor" href="#_3-цели-обработки" aria-label="Permalink to &quot;3. Цели обработки&quot;">​</a></h2><p>Поверенный обрабатывает персональные данные исключительно в следующих целях:</p><ul><li>доставка SMS-сообщений получателям через устройство Поверенного;</li><li>ведение журнала отправленных и принятых сообщений;</li><li>исполнение обязательств перед клиентами Поверенного;</li><li>техническое взаимодействие с API GoSMS.</li></ul><p><strong>Запрещается</strong> использование данных в иных целях, включая передачу третьим лицам, маркетинговую обработку или создание новых баз данных.</p><h2 id="_4-деиствия-с-персональными-данными" tabindex="-1">4. Действия с персональными данными <a class="header-anchor" href="#_4-деиствия-с-персональными-данными" aria-label="Permalink to &quot;4. Действия с персональными данными&quot;">​</a></h2><p>Поверенному разрешаются следующие действия с персональными данными:</p><ul><li>сбор и запись (телефонные номера получателей);</li><li>хранение (в пределах технической необходимости);</li><li>использование (отправка сообщений);</li><li>передача Оператору (синхронизация журналов).</li></ul><p>Все иные действия требуют письменного согласия Оператора.</p><h2 id="_5-обязательства-поверенного" tabindex="-1">5. Обязательства Поверенного <a class="header-anchor" href="#_5-обязательства-поверенного" aria-label="Permalink to &quot;5. Обязательства Поверенного&quot;">​</a></h2><p>Поверенный обязуется:</p><p>5.1. <strong>Конфиденциальность.</strong> Не раскрывать персональные данные третьим лицам без письменного разрешения Оператора, за исключением случаев, предусмотренных законодательством РФ.</p><p>5.2. <strong>Безопасность.</strong> Применять технические и организационные меры защиты персональных данных в соответствии с требованиями ст. 19 ФЗ-152 и Постановления Правительства РФ от 01.11.2012 № 1119:</p><ul><li>контроль доступа к персональным данным;</li><li>антивирусная защита устройств;</li><li>шифрование данных при передаче (HTTPS/TLS);</li><li>регулярное резервное копирование.</li></ul><p>5.3. <strong>Уведомление об инцидентах.</strong> Незамедлительно (но не позднее 24 часов) уведомлять Оператора об инцидентах безопасности, повлёкших или потенциально повлёкших утечку персональных данных.</p><p>5.4. <strong>Законность рассылок.</strong> Самостоятельно обеспечивать наличие согласий получателей на получение сообщений в соответствии с ФЗ-38 «О рекламе» и соблюдать требования <a href="/aup">Правил допустимого использования</a>.</p><p>5.5. <strong>Содействие субъектам.</strong> Содействовать Оператору в реализации прав субъектов персональных данных (запросы на доступ, исправление, удаление данных).</p><p>5.6. <strong>Уничтожение данных.</strong> По завершении поручения или расторжении договора — уничтожить или возвратить Оператору персональные данные в течение <strong>30 (тридцати) рабочих дней</strong>, если иное не предусмотрено законодательством.</p><p>5.7. <strong>Запрет субпоручения.</strong> Не передавать обработку персональных данных другим лицам (субпоручение) без письменного согласия Оператора.</p><p>5.8. <strong>Предоставление информации.</strong> По запросу Оператора предоставлять документацию и иные сведения, подтверждающие соблюдение настоящего Соглашения.</p><h2 id="_6-обязательства-оператора" tabindex="-1">6. Обязательства Оператора <a class="header-anchor" href="#_6-обязательства-оператора" aria-label="Permalink to &quot;6. Обязательства Оператора&quot;">​</a></h2><p>Оператор обязуется:</p><p>6.1. Предоставлять Поверенному необходимые инструкции, разъяснения и ресурсы для выполнения поручения.</p><p>6.2. Уведомлять Поверенного о существенных изменениях в порядке обработки персональных данных.</p><p>6.3. Обеспечивать Поверенному доступ к документации и технической поддержке в объёме, необходимом для исполнения поручения.</p><h2 id="_7-ответственность" tabindex="-1">7. Ответственность <a class="header-anchor" href="#_7-ответственность" aria-label="Permalink to &quot;7. Ответственность&quot;">​</a></h2><p>7.1. Поверенный несёт ответственность за нарушение условий настоящего Соглашения, а также за убытки, причинённые Оператору в результате ненадлежащей обработки персональных данных, в соответствии с законодательством РФ.</p><p>7.2. Поверенный обязан возместить Оператору все штрафы, санкции и убытки, причинённые вследствие нарушений настоящего Соглашения или требований ФЗ-152.</p><h2 id="_8-срок-деиствия" tabindex="-1">8. Срок действия <a class="header-anchor" href="#_8-срок-деиствия" aria-label="Permalink to &quot;8. Срок действия&quot;">​</a></h2><p>8.1. Соглашение действует в течение всего срока использования Поверенным Сервиса GoSMS.</p><p>8.2. Прекращение договора об использовании Сервиса влечёт прекращение настоящего Соглашения.</p><p>8.3. Условия, касающиеся конфиденциальности (разд. 5.1) и уничтожения данных (разд. 5.6), сохраняют силу <strong>5 (пять) лет</strong> после прекращения Соглашения.</p><h2 id="_9-применимое-право-и-разрешение-споров" tabindex="-1">9. Применимое право и разрешение споров <a class="header-anchor" href="#_9-применимое-право-и-разрешение-споров" aria-label="Permalink to &quot;9. Применимое право и разрешение споров&quot;">​</a></h2><p>9.1. Соглашение регулируется Федеральным законом от 27.07.2006 № 152-ФЗ «О персональных данных» и иным законодательством РФ.</p><p>9.2. Споры разрешаются в судебном порядке по месту нахождения Оператора.</p><h2 id="_10-реквизиты-оператора" tabindex="-1">10. Реквизиты Оператора <a class="header-anchor" href="#_10-реквизиты-оператора" aria-label="Permalink to &quot;10. Реквизиты Оператора&quot;">​</a></h2><p><strong>ИП Ульянов Алексей Владимирович</strong><br> ОГРНИП 321132600016985<br> Email: <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a><br> Сайт: <a href="https://gosms.ru" target="_blank" rel="noreferrer">https://gosms.ru</a></p>',50)])])}const u=t(s,[["render",l]]);export{c as __pageData,u as default};
